      m.querySelectorAll('[data-c]').forEach(function (i) { i.onchange = function () { var k = i.dataset.c.split('.'); var s = list[+k[0]]; s.cred = s.cred || {}; if (i.value === '') delete s.cred[k[1]]; else s.cred[k[1]] = +i.value; save(); side(); }; });
