    var loadComments = function () { RH.S.db.from('research_feedback').select('*').eq('project_id', RH.p.id).eq('stage', 'ee_write').order('created_at').then(function (r) { (r.data || []).forEach(function () {}); secs.forEach(function (s) { var box = m.querySelector('[data-cm="' + s.id + '"]'); if (!box) return; var mine = (r.data || []).filter(function (f) { return String(f.evidence || '').indexOf(s.heading) === 0; }); box.innerHTML = mine.map(function (f) { return '<div class="rh-item"><span class="meta"><span class="rh-badge ' + (f.source === 'ai' ? 'ai' : 'ok') + '">' + (f.source === 'ai' ? 'AI' : 'Supervisor') + '</span> ' + RH.date(f.created_at, true) + '</span>' + (f.evidence && f.evidence.length > s.heading.length + 2 ? '<span class="small muted">' + E(f.evidence.slice(s.heading.length + 2)) + '</span>' : '') + '<span class="small" style="white-space:pre-wrap">' + E(f.comment) + '</span></div>'; }).join(''); }); }); };
    drawSecs();
